Account.ready.then(user=>{
 if(user.role!=='admin'){location.replace('/sets.html');return;}
 const $=id=>document.getElementById(id),fields=['subject','topic','status'];let bank=[],selected=new Set(),drafts=new Map(),pending=[],saving=false,page=1,kind='',sort='display_code',direction=1,bulkMode='category';
 const value=q=>drafts.get(q.id)||q;
 const filtered=()=>bank.filter(q=>(!kind||(kind==='scenario'?!!q.case_id:!q.case_id))&&(!$('subject-filter').value||q.subject===$('subject-filter').value)&&(!$('topic-filter').value||q.topic===$('topic-filter').value)&&(!$('status-filter').value||q.status===$('status-filter').value)&&(q.id+' '+q.display_code+' '+(q.case_id||'')+' '+q.text).toLowerCase().includes($('search-table').value.trim().toLowerCase())).sort((a,b)=>direction*(sort==='maximum'?a.maximum-b.maximum:String(a[sort]||'').localeCompare(String(b[sort]||''),undefined,{numeric:true}))||a.id.localeCompare(b.id));
 const pageRows=()=>filtered().slice((page-1)*Number($('page-size').value),page*Number($('page-size').value));
 function counts(){const visible=pageRows();$('selection-bar').hidden=!selected.size;$('selection-count').textContent=selected.size+' selected';$('select-visible').checked=visible.length>0&&visible.every(q=>selected.has(q.id));$('select-visible').indeterminate=visible.some(q=>selected.has(q.id))&&!$('select-visible').checked;$('draft-count').textContent=drafts.size?drafts.size+' unsaved change'+(drafts.size===1?'':'s'):'No unsaved changes';$('draft-count').classList.toggle('pending',!!drafts.size);$('preview-changes').textContent='Review changes'+(drafts.size?' ('+drafts.size+')':'');$('preview-changes').disabled=$('discard-changes').disabled=!drafts.size;$('bulk-category').disabled=bank.some(q=>selected.has(q.id)&&q.case_id);$('bulk-category').title=$('bulk-category').disabled?'Select standalone questions only. Edit linked categories in the shared scenario.':'';}
 function edit(q,key,text){const d={...value(q),[key]:text};if(fields.every(f=>d[f]===q[f]))drafts.delete(q.id);else drafts.set(q.id,d);}
 function render(){const rows=filtered(),size=Number($('page-size').value),pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages);const body=$('question-rows');body.replaceChildren();for(const q of pageRows()){const d=value(q),tr=document.createElement('tr');tr.classList.toggle('selected',selected.has(q.id));function cell(text){const td=document.createElement('td');if(text!==undefined)td.textContent=text;tr.append(td);return td}const check=document.createElement('input');check.type='checkbox';check.checked=selected.has(q.id);check.setAttribute('aria-label','Select '+q.display_code);check.onchange=()=>{check.checked?selected.add(q.id):selected.delete(q.id);render()};cell().append(check);const code=cell(q.display_code||q.id),sub=document.createElement('small');sub.textContent=q.case_id?q.case_id+' · Step '+String.fromCharCode(64+q.case_order):'Standalone';code.append(sub);cell(q.text.length>150?q.text.slice(0,150)+'…':q.text).className='preview-text';cell({single:'Single choice',multi:'Multiple choices',range:'Numerical'}[q.type]||q.type);const category=cell(d.subject),topic=document.createElement('small');topic.textContent=d.topic;category.append(topic);cell(q.maximum);const status=cell(),badge=document.createElement('span');badge.className='status-badge';badge.dataset.status=d.status;badge.textContent=d.status;status.append(badge);if(drafts.has(q.id)){const changed=document.createElement('small');changed.className='edited';changed.textContent='Edited';status.append(changed)}const link=document.createElement('a');link.href='/admin?workflow='+(q.case_id?'scenario':'standalone')+'&question='+encodeURIComponent(q.id);link.textContent='Edit';link.setAttribute('aria-label','Edit '+q.display_code);cell().append(link);body.append(tr)}if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=8;td.textContent='No questions match these filters.';tr.append(td);body.append(tr)}$('page-summary').textContent=rows.length?'Showing '+((page-1)*size+1)+'–'+Math.min(page*size,rows.length)+' of '+rows.length+' questions':'0 questions';$('page-number').textContent=page+' / '+pages;$('previous-page').disabled=page===1;$('next-page').disabled=page===pages;counts();}
 function topics(){const old=$('topic-filter').value,subject=$('subject-filter').value,values=[...new Set(bank.filter(q=>!subject||q.subject===subject).map(q=>q.topic))].sort();$('topic-filter').replaceChildren(new Option('All topics',''),...values.map(v=>new Option(v,v)));$('topic-filter').value=values.includes(old)?old:'';}
 function choices(){const old=$('subject-filter').value,values=[...new Set(bank.map(q=>q.subject))].sort();$('subject-filter').replaceChildren(new Option('All subjects',''),...values.map(v=>new Option(v,v)));$('subject-filter').value=values.includes(old)?old:'';topics();for(const [key,id] of [['subject','subject-options'],['topic','topic-options']])$(id).replaceChildren(...[...new Set(bank.map(q=>q[key]))].sort().map(v=>new Option(v,v)));$('count-all').textContent=bank.length;$('count-standalone').textContent=bank.filter(q=>!q.case_id).length;$('count-scenario').textContent=bank.filter(q=>q.case_id).length;}
 async function load(){try{const data=await Account.request('/api/questions');bank=data;selected.clear();drafts.clear();choices();render();$('table-status').textContent='Loaded '+bank.length+' questions.'}catch(e){$('table-status').textContent='Could not refresh: '+e.message}}
 document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;page=1;document.querySelectorAll('[data-kind]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()});document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{direction=sort===b.dataset.sort?-direction:1;sort=b.dataset.sort;page=1;document.querySelectorAll('th').forEach(th=>th.removeAttribute('aria-sort'));b.closest('th').setAttribute('aria-sort',direction===1?'ascending':'descending');render()});
 $('subject-filter').onchange=()=>{topics();page=1;render()};for(const id of ['topic-filter','status-filter','page-size'])$(id).onchange=()=>{page=1;render()};$('search-table').oninput=()=>{page=1;render()};$('reset-filters').onclick=()=>{for(const id of ['subject-filter','topic-filter','status-filter','search-table'])$(id).value='';topics();page=1;render()};$('previous-page').onclick=()=>{page--;render()};$('next-page').onclick=()=>{page++;render()};
 $('select-visible').onchange=()=>{for(const q of pageRows())$('select-visible').checked?selected.add(q.id):selected.delete(q.id);render()};$('clear-selection').onclick=()=>{selected.clear();render()};
 function openBulk(mode){bulkMode=mode;$('bulk-title').textContent=mode==='category'?'Edit subject / topic':mode==='archive'?'Archive selected questions':'Change status';$('bulk-hint').textContent=selected.size+' selected questions. Changes will be staged for review before saving.';$('category-fields').hidden=mode!=='category';$('status-field').hidden=mode==='category';$('bulk-status').disabled=mode==='archive';$('bulk-status').value=mode==='archive'?'Archived':'Draft';$('bulk-subject').value=$('bulk-topic').value=$('bulk-error').textContent='';$('bulk-dialog').showModal()}
 $('bulk-category').onclick=()=>openBulk('category');$('bulk-status-button').onclick=()=>openBulk('status');$('bulk-archive').onclick=()=>openBulk('archive');$('bulk-cancel').onclick=()=>$('bulk-dialog').close();$('bulk-apply').onclick=()=>{const targets=bank.filter(q=>selected.has(q.id));if(bulkMode==='category'&&targets.some(q=>q.case_id)){$('bulk-error').textContent='Edit linked categories in the shared scenario.';return}const changes=bulkMode==='category'?Object.fromEntries(['subject','topic'].map(f=>[f,$('bulk-'+f).value.trim()]).filter(([,v])=>v)):{status:$('bulk-status').value};if(!Object.keys(changes).length){$('bulk-error').textContent='Enter a subject or topic.';return}for(const q of targets)for(const [key,v] of Object.entries(changes))edit(q,key,v);$('bulk-dialog').close();render();$('table-status').textContent='Changes staged. Review before saving. Scenario publication checks apply when saving.'};
 $('refresh-table').onclick=()=>{if(!drafts.size||confirm('Discard unsaved table changes and refresh?'))load()};$('discard-changes').onclick=()=>{if(!drafts.size||confirm('Discard unsaved table changes?')){drafts.clear();render()}};
 $('preview-changes').onclick=()=>{pending=[];const box=$('change-preview');box.replaceChildren();for(const q of bank){if(!drafts.has(q.id))continue;const changes={};for(const f of fields)if(value(q)[f]!==q[f])changes[f]=value(q)[f].trim();if(Object.values(changes).some(v=>!v)){$('table-status').textContent='Subject and topic cannot be blank.';return}pending.push({id:q.id,revision:q.revision,fields:changes});const p=document.createElement('p');p.textContent=(q.display_code||q.id)+': '+Object.entries(changes).map(([k,v])=>k+' “'+q[k]+'” → “'+v+'”').join('; ');box.append(p)}if(!pending.length)return;$('preview-count').textContent=pending.length+' questions will be updated together.';$('save-message').textContent='';$('review-changes').showModal()};
 $('cancel-changes').onclick=()=>{if(!saving)$('review-changes').close()};$('review-changes').addEventListener('cancel',e=>{if(saving)e.preventDefault()});$('confirm-changes').onclick=async()=>{if(saving)return;saving=true;$('confirm-changes').disabled=$('cancel-changes').disabled=true;$('save-message').textContent='Creating a verified backup and saving…';try{const result=await Account.request('/api/admin/questions-bulk',{changes:pending});for(const change of pending){const q=bank.find(q=>q.id===change.id);Object.assign(q,change.fields);q.revision++;}drafts.clear();selected.clear();choices();render();$('review-changes').close();$('table-status').textContent=result.updated+' questions updated. Backup verified; previous values recorded.';}catch(e){$('save-message').textContent=e.message}finally{saving=false;$('confirm-changes').disabled=$('cancel-changes').disabled=false}};
 window.addEventListener('beforeunload',e=>{if(drafts.size||saving){e.preventDefault();e.returnValue=''}});load();
}).catch(()=>{});
